-- Seeds the gold-copy menu tree from the formerly hardcoded MainNavigation categoryConfigs.
-- Generated once; from here on Menu Designer owns the tree. Idempotent and never overwrites designer edits.
ALTER TABLE public.navigation_menu_nodes ADD COLUMN IF NOT EXISTS target_route VARCHAR(300);
-- target_route is INTERIM: it opens a not-yet-redesigned coded screen and is cleared as each is rebuilt in Page Designer.


UPDATE public.navigation_menu_nodes SET required_capability='menu:platform' WHERE tenant_id='99e99e99-99e9-49e9-89e9-99e99e99e999' AND node_key='platform' AND parent_id IS NULL AND required_capability IS NULL;
UPDATE public.navigation_menu_nodes SET required_capability='menu:system', label='System' WHERE tenant_id='99e99e99-99e9-49e9-89e9-99e99e99e999' AND node_key='system' AND required_capability IS NULL;
